function AttendanceChart() { return <ChartCard title="Attendance Overview"><ChartContainer config={chartConfig} className="h-[220px] w-full"><AreaChart data={attendance} margin={{ left: -10, right: 12, top: 10 }}><defs><linearGradient id="attendanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#818cf8" stopOpacity={0.32}/><stop offset="100%" stopColor="#818cf8" stopOpacity={0.02}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#eef1f6" /><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#94a3b8' }} /><YAxis domain={[0,160]} ticks={[0,40,80,120,160]} tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#94a3b8' }} /><Tooltip content={<ChartTooltipContent />} /><Area type="monotone" dataKey="value" stroke="#6366f1" strokeWidth={2.5} fill="url(#attendanceFill)" /></AreaChart></ChartContainer></ChartCard> }
