      {dialogOpen && <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-900/30 p-4"><div role="dialog" aria-modal="true" aria-labelledby="add-student-title" className="my-8 w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><div><h2 id="add-student-title" className="text-lg font-bold text-slate-900">Add Student</h2><p className="mt-1 text-xs text-slate-500">Create a new student profile and parent account.</p></div><button type="button" onClick={() => setDialogOpen(false)} aria-label="Close dialog" className="rounded-lg p-2 text-slate-400 hover:bg-slate-50 hover:text-slate-700"><X className="size-5" /></button></div><form onSubmit={(event) => { event.preventDefault(); setDialogOpen(false) }} className="flex flex-col gap-4"><div className="grid gap-4 sm:grid-cols-2"><div className="flex flex-col gap-1.5"><label htmlFor="student-name" className="text-xs font-semibold text-slate-700">Full Name</label><input id="student-name" required placeholder="Enter full name" className="h-10 rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-orange-400" /></div><div className="flex flex-col gap-1.5"><label htmlFor="student-class" className="text-xs font-semibold text-slate-700">Class</label><select id="student-class" className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option>Class 1-A</option><option>Class 1-B</option><option>Class 10-A</option></select></div><div className="flex flex-col gap-1.5"><label htmlFor="roll-number" className="text-xs font-semibold text-slate-700">Roll Number</label><input id="roll-number" required placeholder="e.g. 12" className="h-10 rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-orange-400" /></div><div className="flex flex-col gap-1.5"><label htmlFor="dob" className="text-xs font-semibold text-slate-700">Date of Birth</label><input id="dob" type="date" className="h-10 rounded-xl border border-slate-200 px-3 text-sm" /></div><div className="flex flex-col gap-1.5"><label htmlFor="parent-name" className="text-xs font-semibold text-slate-700">Parent Name</label><input id="parent-name" placeholder="Enter parent name" className="h-10 rounded-xl border border-slate-200 px-3 text-sm" /></div><div className="flex flex-col gap-1.5"><label htmlFor="parent-phone" className="text-xs font-semibold text-slate-700">Parent Phone</label><input id="parent-phone" type="tel" placeholder="Enter phone number" className="h-10 rounded-xl border border-slate-200 px-3 text-sm" /></div><div className="flex flex-col gap-1.5 sm:col-span-2"><label htmlFor="parent-email" className="text-xs font-semibold text-slate-700">Parent Email</label><input id="parent-email" required type="email" placeholder="parent@example.com" className="h-10 rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-orange-400" /><span className="text-[11px] text-slate-400">Account credentials will be sent here.</span></div><div className="flex flex-col gap-1.5 sm:col-span-2"><label htmlFor="address" className="text-xs font-semibold text-slate-700">Address</label><textarea id="address" rows={3} placeholder="Enter home address" className="rounded-xl border border-slate-200 px-3 py-2 text-sm outline-none focus:border-orange-400" /></div></div><div className="flex justify-end gap-3 border-t border-slate-100 pt-5"><button type="button" onClick={() => setDialogOpen(false)} className="h-10 rounded-xl px-4 text-sm font-medium text-slate-600 hover:bg-slate-50">Cancel</button><button type="submit" className="h-10 rounded-xl bg-[#FF6B35] px-5 text-sm font-semibold text-white hover:bg-[#e85a27]">Add Student</button></div></form></div></div>}
